package com.bookstore.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.util.*;
@Entity @Table(name="customers")
public class Customer { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Size(max=120) private String name; @NotBlank @Email @Column(nullable=false,unique=true) private String email; @Size(max=20) private String phone; @Size(max=300) private String address; @OneToMany(mappedBy="customer") private List<Order> orders=new ArrayList<>(); public Customer(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public List<Order> getOrders(){return orders;} public void setOrders(List<Order> v){orders=v;} }
